import React from 'react';

const Sidebar: React.FC = () => {
  return (
    <aside style={{ width: '200px', background: '#f0f0f0', padding: '1rem' }}>
      <h2>Menu</h2>
      <ul>
        <li>Dashboard</li>
        <li>Campaigns</li>
        <li>Settings</li>
      </ul>
    </aside>
  );
};

export default Sidebar;
